import{_ as e,o as r,c as t,a5 as i}from"./chunks/framework.CXroN2RO.js";const c=JSON.parse('{"title":"リアルタイムグラフィックスを学ぶ","description":"","frontmatter":{"title":"リアルタイムグラフィックスを学ぶ","study":{"source":"RenderingWiki","status":"published","summary":"GPU・数学・パイプライン・APIの本文を順番に読み、描画の実践へ進むための入口。","section":"learning","format":"path","domain":"graphics","collection":"rendering","order":-1}},"headers":[],"relativePath":"graphics/rendering-intro.md","filePath":"graphics/rendering-intro.md"}'),h={name:"graphics/rendering-intro.md"};function n(d,a,p,o,l,s){return r(),t("div",null,[...a[0]||(a[0]=[i('<div id="リアルタイムグラフィックス完全wiki" class="study-legacy-anchor" aria-hidden="true"></div><h1 id="リアルタイムグラフィックスを学ぶ" tabindex="-1">リアルタイムグラフィックスを学ぶ <a class="header-anchor" href="#リアルタイムグラフィックスを学ぶ" aria-label="Permalink to &quot;リアルタイムグラフィックスを学ぶ&quot;">​</a></h1><p>GPUとレンダリングを順番に学ぶための入口です。各項目の詳しい説明は技術辞典にあり、このガイドでは読む順序と分野のつながりを案内します。</p><p>まず全体の読み順を選び、必要な本文を読み、実践教材で確かめます。既に知っている内容は飛ばし、疑問のある項目へ戻って使えます。</p><ul><li><a href="/study/guide/rendering/roadmap.html">学習を始める</a></li><li><a href="/study/guide/rendering/about.html">描画の学習ガイドについて</a></li><li><a href="/study/guide/rendering/timeline.html">技術全史年表</a></li></ul><h2 id="gpu基礎" tabindex="-1">GPU基礎 <a class="header-anchor" href="#gpu基礎" aria-label="Permalink to &quot;GPU基礎&quot;">​</a></h2><p>GPUとは何か、CPUとの役割分担、SIMTアーキテクチャ、メモリ階層。すべての土台となるハードウェアの理解。</p><p><a href="/study/hardware/gpu/what-is-gpu.html">この項目を読む</a></p><h2 id="_3d数学" tabindex="-1">3D数学 <a class="header-anchor" href="#_3d数学" aria-label="Permalink to &quot;3D数学&quot;">​</a></h2><p>ベクトル・行列・座標変換・カメラ・クォータニオン。レンダリングを支える数学を「なぜ」から理解する。</p><p><a href="/study/math/rendering/vector.html">この項目を読む</a></p><h2 id="レンダリングパイプライン" tabindex="-1">レンダリングパイプライン <a class="header-anchor" href="#レンダリングパイプライン" aria-label="Permalink to &quot;レンダリングパイプライン&quot;">​</a></h2><p>Vertex Shader から Fragment Shader、そして Mesh Shader まで。頂点がピクセルになるまでの全工程。</p><p><a href="/study/graphics/pipeline/overview.html">この項目を読む</a></p><h2 id="シェーダ言語" tabindex="-1">シェーダ言語 <a class="header-anchor" href="#シェーダ言語" aria-label="Permalink to &quot;シェーダ言語&quot;">​</a></h2><p>HLSL / GLSL / WGSL / MSL / SPIR-V。言語間の対応関係とコンパイルパイプラインを横断的に比較。</p><p><a href="/study/graphics/shader/overview.html">この項目を読む</a></p><h2 id="グラフィックスapi" tabindex="-1">グラフィックスAPI <a class="header-anchor" href="#グラフィックスapi" aria-label="Permalink to &quot;グラフィックスAPI&quot;">​</a></h2><p>OpenGL から DirectX12・Vulkan・Metal・WebGPU へ。APIの進化の歴史と、明示的APIの設計思想。</p><p><a href="/study/graphics/api/history.html">この項目を読む</a></p><h2 id="gpuコンピューティング" tabindex="-1">GPUコンピューティング <a class="header-anchor" href="#gpuコンピューティング" aria-label="Permalink to &quot;GPUコンピューティング&quot;">​</a></h2><p>Compute Shader、Warp/Wave、Shared Memory、Reduction、Prefix Sum。GPUを汎用計算機として使いこなす。</p><p><a href="/study/graphics/compute/compute-shader.html">この項目を読む</a></p><h2 id="ライティングとgi" tabindex="-1">ライティングとGI <a class="header-anchor" href="#ライティングとgi" aria-label="Permalink to &quot;ライティングとGI&quot;">​</a></h2><p>PBR・IBL・シャドウ・SSAO・SSR・レイトレーシング・Lumen。光の物理と近似手法の系譜。</p><p><a href="/study/graphics/lighting/pbr.html">この項目を読む</a></p><h2 id="ポストプロセスとaa" tabindex="-1">ポストプロセスとAA <a class="header-anchor" href="#ポストプロセスとaa" aria-label="Permalink to &quot;ポストプロセスとAA&quot;">​</a></h2><p>TAA・FXAA・DLSS・FSR・XeSS。現代のゲームグラフィックスを支える画像処理技術。</p><p><a href="/study/graphics/postprocess/overview.html">この項目を読む</a></p><h2 id="gpu最適化" tabindex="-1">GPU最適化 <a class="header-anchor" href="#gpu最適化" aria-label="Permalink to &quot;GPU最適化&quot;">​</a></h2><p>RenderGraph、GPU Driven Rendering、RenderDoc / PIX / Nsight によるプロファイリング。</p><p><a href="/study/graphics/optimization/basics.html">この項目を読む</a></p><h2 id="エンジンのレンダラー" tabindex="-1">エンジンのレンダラー <a class="header-anchor" href="#エンジンのレンダラー" aria-label="Permalink to &quot;エンジンのレンダラー&quot;">​</a></h2><p>Unity SRP / URP / HDRP、Unreal Engine のレンダラー。商用エンジンの内部実装を理解する。</p><p><a href="/study/graphics/engine/unity-renderer.html">この項目を読む</a></p><h2 id="ゼロからレンダラーを作る" tabindex="-1">ゼロからレンダラーを作る <a class="header-anchor" href="#ゼロからレンダラーを作る" aria-label="Permalink to &quot;ゼロからレンダラーを作る&quot;">​</a></h2><p>実践・サンプルの教材です。CPUからGPUまで、1フレームが描画されるまでを設計とコード断片で追います。</p><p><a href="/study/graphics/capstone/01-design.html">この項目を読む</a></p><h2 id="学習ロードマップ" tabindex="-1">学習ロードマップ <a class="header-anchor" href="#学習ロードマップ" aria-label="Permalink to &quot;学習ロードマップ&quot;">​</a></h2><p>どこから読めばいいか迷ったらここ。知識ツリーに沿った推奨学習順序を提示。</p><p><a href="/study/guide/rendering/roadmap.html">この項目を読む</a></p>',41)])])}const m=e(h,[["render",n]]);export{c as __pageData,m as default};
